{
  "technical_and_design_decisions": [
    "Use Spring WebSocket for native WebSocket sink implementation.",
    "Use Gradle Shadow plugin to create uber-jar for custom modules.",
    "Use Hadoop HDFS Java API for uploading jars to HDFS.",
    "Use Bamboo as CI server; configure Windows agent for integration tests.",
    "Use SonarQube for static analysis and configure notifications for committers.",
    "Use xd/lib as shared library directory; customize classloader to load from there.",
    "For version conflicts, bundle required jar versions within the custom module.",
    "Replace Artifactory Gradle plugin with direct Gradle wrapper commands for more control.",
    "Enable Gradle's maxParallelForks for parallel test execution.",
    "Disable embedded Hadoop in tests to run against external Hadoop cluster."
  ],
  "assumptions": [
    "The development team has experience with Spring Framework 6.0, Java 17, Gradle, and Bamboo.",
    "The custom module build process already exists and only needs uber-jar packaging addition.",
    "The WebSocket sink is a new feature that fits into existing sink extension points.",
    "The CI infrastructure is based on Bamboo with existing Linux agents; Windows agent can be provisioned.",
    "The increase in WARN logs is due to recent code changes and can be resolved by fixing PMD/Sonar violations.",
    "The npm-cache research is for caching Node.js dependencies if the project has a frontend; otherwise, it applies to Gradle dependency caching.",
    "The distributed JVM test feature refers to Gradle's ability to distribute tests across multiple JVMs.",
    "The project uses SonarQube for code quality and has integration with CI for notifications.",
    "The shared library location (xd/lib) is accessible at runtime by all custom modules.",
    "The Windows environment for CI has necessary permissions to install services (Redis, RabbitMQ)."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Create documentation for custom module development standards and patterns",
      "activity_description": "Write documentation (markdown/Confluence) covering recommended standards and patterns for building custom modules, including examples.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Configure build to produce uber-jar for custom module",
      "activity_description": "Add Gradle Shadow plugin configuration to build a fat jar containing all dependencies for the custom module.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement HDFS deployment script for uber-jar",
      "activity_description": "Write a script or CI step using Hadoop HDFS Java API to upload the generated uber-jar to HDFS.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4",
      "activity_name": "Test HDFS deployment and container deployment",
      "activity_description": "Verify that the uber-jar is correctly uploaded to HDFS and that newly arriving containers can pull and deploy the module.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A5",
      "activity_name": "Design and implement native WebSocket sink",
      "activity_description": "Implement a WebSocket sink using Spring WebSocket (or native Java WebSocket API) that integrates with the existing module system.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A6",
      "activity_name": "Write integration tests for WebSocket sink",
      "activity_description": "Create integration tests to verify full-duplex communication over WebSocket sink.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7",
      "activity_name": "Document WebSocket sink usage",
      "activity_description": "Add documentation for the new WebSocket sink, including configuration and examples.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A8",
      "activity_name": "Research CI caching options (npm-cache and alternatives)",
      "activity_description": "Investigate npm-cache and other dependency caching solutions to improve CI build stability and reliability; prototype the most promising option.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "Document CI caching recommendations",
      "activity_description": "Record findings and provide a recommendation for CI caching strategy.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A10",
      "activity_name": "Enable distributed JVM tests in CI",
      "activity_description": "Configure CI to run tests across multiple JVMs (e.g., using Gradle's test distribution feature).",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A11",
      "activity_name": "Replace Artifactory Gradle task with command-line Gradle wrapper",
      "activity_description": "Modify CI build scripts to call ./gradlew directly instead of using the Artifactory Gradle plugin.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A12",
      "activity_name": "Configure tests to run with embedded Hadoop disabled",
      "activity_description": "Adjust test configuration to disable embedded Hadoop and run against an external Hadoop cluster.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A13",
      "activity_name": "Configure maxParallelForks for parallel test execution",
      "activity_description": "Set Gradle's maxParallelForks property to enable parallel test execution.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A14",
      "activity_name": "Validate CI pipeline changes",
      "activity_description": "Run the CI pipeline to verify all changes (distributed tests, command-line Gradle, embedded Hadoop off, parallel forks) work correctly.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A15",
      "activity_name": "Analyze WARN logs increase and identify root causes",
      "activity_description": "Examine recent WARN log increases, correlate with code changes, and identify sources.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A16",
      "activity_name": "Fix PMD/Sonar violations in codebase",
      "activity_description": "Resolve static analysis violations reported by PMD and SonarQube.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A17",
      "activity_name": "Configure SonarQube notifications for committers",
      "activity_description": "Set up SonarQube to notify the committer (e.g., via email or Slack) when new violations are introduced.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A18",
      "activity_name": "Provision and configure Windows Bamboo agent",
      "activity_description": "Set up a Windows machine as a Bamboo agent, including necessary environment variables and connectivity.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A19",
      "activity_name": "Install and configure PowerShell on Windows agent",
      "activity_description": "Ensure PowerShell is available and configured for running CI scripts.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A20",
      "activity_name": "Set up required services (Redis, RabbitMQ) on Windows",
      "activity_description": "Install and configure Redis and RabbitMQ services on the Windows agent for integration tests.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A21",
      "activity_name": "Create and configure CI task for Windows integration tests",
      "activity_description": "Define a Bamboo job/task that runs integration tests on the Windows agent.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A22",
      "activity_name": "Run and validate Windows integration tests",
      "activity_description": "Execute the Windows integration test suite and verify all tests pass.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A23",
      "activity_name": "Define shared library location (xd/lib) and update classloader configuration",
      "activity_description": "Establish xd/lib as the common directory for shared jars and modify the classloader to load from this location.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A24",
      "activity_name": "Implement version conflict resolution strategy (bundle in module)",
      "activity_description": "Provide a mechanism to bundle specific jar versions within a custom module when version conflicts arise with xd/lib.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A25",
      "activity_name": "Test shared library usage with multiple custom modules",
      "activity_description": "Verify that multiple custom modules can correctly share jars from xd/lib and that version bundling works as expected.",
      "most_likely_effort": 1
    }
  ],
  "reported_total": {
    "most_likely_effort": 54
  }
}

